{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01W1BSXiuuZuD1c7AZxfxvMT","type":"tool_result","content":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-patient-chart</repo>
