1: import { useMemo } from 'react';
2: import useSWR from 'swr';
3: import useSWRImmutable from 'swr/immutable';
4: import useSWRInfinite from 'swr/infinite';
5: import { openmrsFetch, restBaseUrl, useAttachments, useConfig, type FetchResponse } from '@openmrs/esm-framework';
6: import { getAttachmentBytesUrl } from '@openmrs/esm-patient-common-lib';
7: import { type ConfigObject } from '../config-schema';
8: import type {
9:   Concept,
10:   DiagnosisPayload,
11:   EncountersFetchResponse,
12:   PatientNote,
13:   RESTPatientNote,
14:   VisitNotePayload,
15: } from '../types';
16: 
17: export interface SavedVisitNoteImage {
18:   id: string;
19:   src: string;
20:   description?: string;
21:   filename?: string;
22: }
23: 
24: /**
25:  * The images already recorded on a visit note's encounter. Nothing is fetched until an
26:  * encounter UUID is known, so the create form makes no request.
27:  */
28: export function useVisitNoteImages(patientUuid: string, encounterUuid?: string) {
29:   const { data, isLoading, error } = useAttachments(encounterUuid ? patientUuid : null, false, encounterUuid);
30: 
31:   const images = useMemo<Array<SavedVisitNoteImage>>(
32:     () =>
33:       data
34:         .filter((attachment) => attachment.bytesContentFamily === 'IMAGE')
35:         .map((attachment) => ({
36:           id: attachment.uuid,
37:           src: getAttachmentBytesUrl(attachment.uuid),
38:           description: attachment.comment,
39:           filename: attachment.filename,
40:         })),
41:     [data],
42:   );
43: 
44:   return { images, isLoading, error };
45: }
46: 
47: interface UseVisitNotes {
48:   visitNotes: Array<PatientNote> | null;
49:   error: Error;
50:   isLoading: boolean;
51:   isValidating?: boolean;
52:   mutateVisitNotes: () => void;
53: }
54: 
55: export function useVisitNotes(patientUuid: string): UseVisitNotes {
56:   const {
57:     visitNoteConfig: { encounterNoteTextConceptUuid, visitDiagnosesConceptUuid },
58:   } = useConfig<ConfigObject>();
59: 
60:   const customRepresentation =
61:     'custom:(uuid,display,encounterDatetime,patient,obs,' +
62:     'encounterProviders:(uuid,display,' +
63:     'encounterRole:(uuid,display),' +
64:     'provider:(uuid,person:(uuid,display))),' +
65:     'diagnoses';
66:   const encountersApiUrl = `${restBaseUrl}/encounter?patient=${patientUuid}&obs=${visitDiagnosesConceptUuid}&v=${customRepresentation}`;
67: 
68:   const { data, error, isLoading, isValidating, mutate } = useSWR<{ data: EncountersFetchResponse }, Error>(
69:     encountersApiUrl,
70:     openmrsFetch,
71:   );
72: 
73:   const mapNoteProperties = (note: RESTPatientNote, index: number): PatientNote => ({
74:     id: `${index}`,
75:     diagnoses: note.diagnoses
76:       .filter((diagnosis) => !diagnosis.voided)
77:       .map((diagnosisData) => diagnosisData.display)
78:       .filter((val) => val)
79:       .join(', '),
80:     encounterDate: note.encounterDatetime,
81:     encounterNote: note.obs.find((observation) => observation.concept.uuid === encounterNoteTextConceptUuid)?.value,
82:     encounterNoteRecordedAt: note.obs.find((observation) => observation.concept.uuid === encounterNoteTextConceptUuid)
83:       ?.obsDatetime,
84:     encounterProvider: note?.encounterProviders[0]?.provider?.person?.display,
85:     encounterProviderRole: note?.encounterProviders[0]?.encounterRole?.display,
86:   });
87: 
88:   const formattedVisitNotes = data?.data?.results
89:     ?.map(mapNoteProperties)
90:     ?.sort((noteA, noteB) => new Date(noteB.encounterDate).getTime() - new Date(noteA.encounterDate).getTime());
91: 
92:   return {
93:     visitNotes: data ? formattedVisitNotes : null,
94:     error,
95:     isLoading,
96:     isValidating,
97:     mutateVisitNotes: mutate,
98:   };
99: }
100: 
101: export function fetchDiagnosisConceptsByName(searchTerm: string, diagnosisConceptClass: string) {
102:   const customRepresentation = 'custom:(uuid,display)';
103:   const url = `${restBaseUrl}/concept?name=${searchTerm}&searchType=fuzzy&class=${diagnosisConceptClass}&v=${customRepresentation}`;
104: 
105:   return openmrsFetch<Array<Concept>>(url).then(({ data }) => Promise.resolve(data['results']));
106: }
107: 
108: /**
109:  * Fetch classes for stored coded diagnoses in one cached request. Unresolved references
110:  * are omitted by the endpoint; return null so the form can retain its certainty action.
111:  */
112: export function useDiagnosisConceptClasses(conceptUuids: Array<string>) {
113:   const { data, error, isLoading } = useSWRImmutable<
114:     FetchResponse<Record<string, { conceptClass?: { uuid: string } }>>,
115:     Error
116:   >(
117:     conceptUuids.length > 0
118:       ? `${restBaseUrl}/conceptreferences?references=${conceptUuids.join(',')}&v=custom:(uuid,conceptClass:(uuid))`
119:       : null,
120:     openmrsFetch,
121:   );
122: 
123:   const conceptClassByUuid = useMemo<Record<string, string | null>>(
124:     () =>
125:       data?.data
126:         ? Object.fromEntries(conceptUuids.map((uuid) => [uuid, data.data[uuid]?.conceptClass?.uuid ?? null]))
127:         : {},
128:     [conceptUuids, data],
129:   );
130: 
131:   return { conceptClassByUuid, error, isLoading };
132: }
133: 
134: export function saveVisitNote(abortController: AbortController, payload: VisitNotePayload) {
135:   return openmrsFetch(`${restBaseUrl}/encounter`, {
136:     headers: {
137:       'Content-Type': 'application/json',
138:     },
139:     method: 'POST',
140:     body: payload,
141:     signal: abortController.signal,
142:   });
143: }
